#include <vector>
#include <array>
#include <omp.h>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    // Initialise the output array to zeros
    bins.fill(0);

    // Parallel counting with a private array per thread
    #pragma omp parallel
    {
        // Each thread gets its own zero‑initialised counter array
        std::array<size_t, 10> private_bins{};

        // Distribute the work among threads
        #pragma omp for
        for (size_t i = 0; i < x.size(); ++i) {
            double val = x[i];
            // Determine the bin index (0‑9). Values at exactly 100 go to bin 9.
            size_t bin = static_cast<size_t>(val / 10.0);
            if (bin >= 10) bin = 9;
            ++private_bins[bin];
        }

        // Merge the private counts into the shared result (critical to avoid races)
        #pragma omp critical
        {
            for (size_t b = 0; b < 10; ++b) {
                bins[b] += private_bins[b];
            }
        }
    }
}
